# Homebrew formula for g4.
#
# GENERATED by rules_brew -- do not edit by hand;
# the next release overwrites this file.
class G4 < Formula
  desc "Linear-trunk version control: FUSE mount plus git collaboration commands"
  homepage "https://github.com/qzmfranklin/homebrew-tap"
  # Platform choice lives in the argument, not in an on_macos block:
  # brew does not allow `url`/`sha256` inside an on_system block.
  # macOS is one universal (arm64 + x86_64) binary, so it needs no arch split.
  url on_system_conditional(
    macos: "https://github.com/qzmfranklin/homebrew-tap/releases/download/g4-0.1.0/g4-darwin-universal.tar.xz",
    linux: on_arch_conditional(
      arm:   "https://github.com/qzmfranklin/homebrew-tap/releases/download/g4-0.1.0/g4-linux-arm64.tar.xz",
      intel: "https://github.com/qzmfranklin/homebrew-tap/releases/download/g4-0.1.0/g4-linux-amd64.tar.xz",
    ),
  )
  version "0.1.0"
  sha256 on_system_conditional(
    macos: "b925dabc32a82f0756d0649842c527534faf80852bccba568c09b4849b42dc71",
    linux: on_arch_conditional(
      arm:   "1a3c269ce6d2e98ec8cf753bf33c89a0e4d8e6f87fca7f6c24637d69979844c3",
      intel: "6ed4fded5bfe569273730b61af4b447111a51dcea8f24be5f8ddb558c12289cc",
    ),
  )
  license :cannot_represent

  def install
    bin.install "g4"

    # The SIX git-* links: git's external-command mechanism runs `git-<cmd>` from
    # PATH when `git <cmd>` matches no builtin or alias, so plain `git land` (and
    # siblings) work with zero per-repo configuration. The g4 binary dispatches on
    # argv[0]: a `git-<cmd>` basename is rewritten to `g4 git <cmd>` before parsing
    # (RFD 0016 § argv[0] dispatch). The ad-hoc codesign below signs the one Mach-O
    # every link points at, so the symlinks need no signing of their own.
    %w[land sync fold mend view web].each do |cmd|
      bin.install_symlink bin/"g4" => "git-#{cmd}"
    end

    # Ad-hoc codesign on macOS. This is INTENTIONAL and load-bearing, not a
    # workaround: the binary is unsigned, and macOS refuses to exec an unsigned
    # or stale-signed Mach-O. Writing the file also invalidates any prior
    # signature, so it must be re-signed after install.
    #
    # chmod first: Homebrew stages files read-only, and both xattr and codesign
    # need to WRITE to the binary (xattr fails with EACCES otherwise).
    if OS.mac?
      chmod 0755, bin/"g4"
      system "/usr/bin/xattr", "-cr", bin/"g4"
      system "/usr/bin/codesign", "--force", "--sign", "-", bin/"g4"
    end
  end

  def post_install
    linked = HOMEBREW_PREFIX/"bin/g4"
    if linked.exist? && !linked.symlink?
      opoo <<~EOS
        Replacing a non-Homebrew g4 at #{linked}.
        That file was almost certainly left by the legacy install script.
        The Homebrew-managed g4 is now the one on your PATH.
      EOS
      linked.unlink
    end

    # Idempotent, and also repairs the case where the legacy binary was
    # deleted by hand: brew never created the symlink, so the tool was
    # missing from PATH entirely.
    linked.make_relative_symlink(bin/"g4") unless linked.symlink?
  end


  def caveats
    <<~EOS
      g4 ships two working surfaces at this version:

        g4 mount    the FUSE virtual filesystem
        g4 git      the collaboration group: land, sync, fold, mend, view, web

      Every other subcommand (umount, sync, diff, land, pick, revert, log, undo,
      br, stat, bisect, serve) is a stub at this version.

      The git group also works as plain git commands: this formula links git-land,
      git-sync, git-fold, git-mend, git-view and git-web to the g4 binary, and
      git's external-command mechanism runs `git-<cmd>` from PATH — so `git land`,
      `git sync`, `git fold`, `git mend`, `git view` and `git web` work in any
      repository with zero per-repo configuration.

      `g4 mount` requires macFUSE. The formula deliberately declares no
      depends_on: the git group never touches FUSE, and a missing macFUSE is
      detected at runtime with the remedy:

        brew install --cask macfuse

      The published binary is ad-hoc signed, not notarized. Homebrew strips the
      quarantine attribute on install, so it runs when installed through brew; a
      binary downloaded directly from the release page may additionally need
      `xattr -cr <path>` before macOS will exec it.
    EOS
  end

  test do
    # --help smokes only: the TUI (`g4 git view`) and the web server
    # (`g4 git web`) are interactive and are not formula-tested. Assert on the
    # usage lines, which survive argument changes, rather than on about text.
    assert_match(/Usage: g4 git/, shell_output("#{bin}/g4 git --help"))
    assert_match(/Usage: g4 git land/, shell_output("#{bin}/g4 git land --help"))
  end
end
